sql-injection.example:
// WRONG — concatenation opens injection
String query = "SELECT * FROM users WHERE name = '" + userInput + "'";

// CORRECT — parameterized
String query = "SELECT account_balance FROM user_data WHERE user_name = ?";
PreparedStatement pstmt = connection.prepareStatement(query);
pstmt.setString(1, customerName);
ResultSet results = pstmt.executeQuery();

// CORRECT — OleDb parameterized query
String query = "SELECT account_balance FROM user_data WHERE user_name = ?";
OleDbCommand command = new OleDbCommand(query, connection);
command.Parameters.Add(new OleDbParameter("customerName", CustomerName.Text));
OleDbDataReader reader = command.ExecuteReader();

// CORRECT — named parameter
Query safeHQLQuery = session.createQuery("from Inventory where productID=:productid");
safeHQLQuery.setParameter("productid", userSuppliedParameter);

dynamic-sql-exceptions.example:
// Allow-list for table names
String tableName;
switch(PARAM) {
   case "Value1": tableName = "fooTable"; break;
   case "Value2": tableName = "barTable"; break;
   default: throw new InputValidationException("unexpected value");
}

// Allow-list for sort order
String sql = "SELECT * FROM orders ORDER BY amount " + (sortAsc ? "ASC" : "DESC");

sanitization.example:
import DOMPurify from 'dompurify';
const clean = DOMPurify.sanitize(userHtml);
// Do NOT mutate the sanitized output afterward
element.innerHTML = clean;
